# writes src/core/metrics.luau from the shipped fonts: python scripts/metrics.py
from fontTools.ttLib import TTFont

FACES = {"display": "fonts/display-600.ttf", "text": "fonts/text-400.ttf", "textMedium": "fonts/text-500.ttf", "mono": "fonts/mono-500.ttf"}

out = [
    "--!strict",
    "-- advance widths of the shipped faces, generated by scripts/metrics.py. layout needs text widths before any instance",
    "-- exists, and TextService only measures custom fonts by yielding",
    "",
    "local metrics = {}",
    "",
    "local FACES: { [string]: { [number]: number } } = {",
]
averages = {}
for name, path in FACES.items():
    font = TTFont(path)
    upem = font["head"].unitsPerEm
    cmap = font.getBestCmap()
    hmtx = font["hmtx"]
    widths = [round(hmtx[cmap[c]][0] / upem, 3) if c in cmap else 0.5 for c in range(32, 127)]
    averages[name] = round(sum(widths) / len(widths), 3)
    out.append("\t%s = { %s }," % (name, ", ".join(str(w) for w in widths)))
out += [
    "}",
    "",
    "-- px width of text at a size; bytes outside printable ascii count as the face's average. markup is not stripped",
    "function metrics.width(face: string, text: string, size: number): number",
    "\tlocal table_ = FACES[face]",
    "\tlocal total = 0",
    "\tfor i = 1, #text do",
    "\t\tlocal byte = string.byte(text, i) :: number",
    "\t\ttotal += table_[byte - 31] or 0.5",
    "\tend",
    "\treturn total * size",
    "end",
    "",
    "return metrics",
    "",
]
open("src/core/metrics.luau", "w", newline="\n").write("\n".join(out))
print(averages)
